/**
 * Mirrors the app design tokens (code/web/src/theme/tokens.ts, plus the illustration tones derived by
 * code/web/src/ui/illustrations/palette.ts) into plain CSS custom properties:
 *
 *   src/login/styles/tokens.generated.css
 *
 * Run `npm run sync-tokens` after changing the tokens in code/web/. The generated file is committed, so
 * the theme builds (for example in a container) without the code/web/ folder. `tokens.test.ts` fails when
 * the committed file drifts from code/web/.
 *
 * Schemes: dark ("Ink") is the default when the browser has no preference, like the app; light
 * ("Linen") applies under `prefers-color-scheme: light`. The night-feed scheme is not used on a login page.
 */
import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { DARK, LIGHT, RADIUS, type SchemeTokens } from '../../web/src/theme/tokens';
import { tone } from '../../web/src/ui/illustrations/palette';
import { mix } from '../../web/src/ui/illustrations/color';

export const OUTPUT = fileURLToPath(new URL('../src/login/styles/tokens.generated.css', import.meta.url));

type Scheme = 'light' | 'dark';

/** Status colours use the category pair of their status (docs/design/TOKENS.md): success=feeding, warning=diaper, error=health, info=sleep. */
function schemeVars(t: SchemeTokens, scheme: Scheme): Record<string, string> {
  const vars: Record<string, string> = {
    '--br-bg': t.background,
    '--br-surface': t.surface,
    '--br-raised': t.surfaceRaised,
    '--br-hairline': t.hairline,
    '--br-text': t.text,
    '--br-muted': t.textMuted,
    '--br-accent': t.accent,
    '--br-on-accent': t.onAccent,
    '--br-selection': t.selection,
    '--br-on-selection': t.onSelection,
    '--br-ink2': t.ink2,
    '--br-success': t.success,
    '--br-on-success': t.onSuccess,
    '--br-warning': t.warning,
    '--br-on-warning': t.onWarning,
    '--br-error': t.error,
    '--br-on-error': t.onError,
    '--br-info': t.info,
    '--br-on-info': t.onInfo,
    '--br-success-bg': t.category.feeding.bg,
    '--br-warning-bg': t.category.diaper.bg,
    '--br-error-bg': t.category.health.bg,
    '--br-info-bg': t.category.sleep.bg,
    '--br-card-shadow': t.cardShadow,
    '--br-scrim': t.scrim,
    '--br-grain-opacity': String(t.grainOpacity),
  };
  // Hero illustration tones (same derivation as the app: palette.ts).
  const materials: Record<string, ReturnType<typeof tone>> = {
    cloud: tone(scheme, 'sleep'),
    moon: tone(scheme, 'diaper', 'light', 0.3),
    glass: tone(scheme, 'feeding'),
    teat: tone(scheme, 'diaper', 'light', 0.3),
    milk: tone(scheme, 'cream', 'cream'),
  };
  for (const [name, m] of Object.entries(materials)) {
    vars[`--il-${name}-hi`] = m.hi;
    vars[`--il-${name}-mid`] = m.mid;
    vars[`--il-${name}-lo`] = m.lo;
    // Gradient end stop: the app mixes halfway to the shade in light, uses the shade in dark.
    vars[`--il-${name}-end`] = scheme === 'light' ? mix(m.mid, m.lo, 0.4) : m.lo;
  }
  // Volume overlay (top-left highlight, soft rim shade): opacities of IllustrationFrame.tsx.
  vars['--il-vol-white'] = scheme === 'light' ? '0.42' : '0.36';
  vars['--il-vol-rim'] = scheme === 'light' ? '0.42' : '0.6';
  vars['--il-shine'] = scheme === 'light' ? '0.62' : '0.5';
  return vars;
}

const block = (vars: Record<string, string>, indent: string) =>
  Object.entries(vars)
    .map(([k, v]) => `${indent}${k}: ${v};`)
    .join('\n');

export function buildTokensCss(): string {
  const radii = Object.entries(RADIUS)
    .map(([k, v]) => `  --br-radius-${k}: ${v}px;`)
    .join('\n');
  return `/*
 * GENERATED by scripts/sync-tokens.ts from code/web/src/theme/tokens.ts and the illustration palette.
 * Do not edit by hand: change the tokens in code/web/ and run \`npm run sync-tokens\`.
 */
:root {
  color-scheme: dark;
${block(schemeVars(DARK, 'dark'), '  ')}
${radii}
}

@media (prefers-color-scheme: light) {
  :root {
    color-scheme: light;
${block(schemeVars(LIGHT, 'light'), '    ')}
  }
}
`;
}
if (process.argv[1]?.endsWith('sync-tokens.ts')) {
  writeFileSync(OUTPUT, buildTokensCss());
  console.log(`wrote ${OUTPUT}`);
}
